    "账号简称、不含 https:// 的登录地址，或 op account list 显示的 ID。",
  "The agent reads local diagnostics and checks AgentShare Client source. It asks before applying a fix and leaves the report in this session for review.":
    "Agent 会读取本地诊断并检查 AgentShare Client 源码，应用修复前先询问，并将报告留在此会话供审查。",
  "The annotation was kept without the screenshot.": "标注已保留，但不含截图。",
