    "应用或截图后端未提供经过验证的辅助功能数据。",
  "The attachment is unavailable.": "附件不可用。",
  "The authentication request expired.": "身份验证请求已过期。",
  "The auto-settle setting could not be changed.": "无法修改自动整理设置。",
  "The boxes below are whatever was last read, and empty if nothing has been read yet.":
    "下方勾选框显示上次读取的状态，尚未读取时为空。",
