  "The environment could not be updated.": "无法更新该执行环境。",
  "The environment couldn't load this {0}'s diff. Try again, or view the changes on {1}.":
    "执行电脑无法加载此{0}的差异。请重试，或在 {1} 上查看改动。",
  "The environment is not connected.": "环境未连接。",
  "The environment is saved and will reconnect on app startup.":
    "环境已保存，应用启动时会重新连接。",
  "The environment's server leases devices from your Simlock gateway and releases them when they close.":
    "环境服务器从 Simlock 网关租用设备，并在关闭时释放。",
  "The environment's server signs in to Expo and starts the sessions. Without a token here it uses EXPO_TOKEN, then its eas login.":
    "环境服务器登录 Expo 并启动会话。未设置令牌时，依次使用 EXPO_TOKEN 和 eas 登录状态。",
  "The extension isn't ready yet. Try again in a moment.": "扩展尚未就绪，请稍后重试。",
  "The file could not be loaded. Please try again.": "无法加载文件，请重试。",
  "The folder for threads without a project could not be created.": "无法创建无项目会话的文件夹。",
  "The guest loses access and the link stops working.": "访客将失去访问权限，链接会失效。",
  "The guest sees the thread as you do, including command output and the agent's reasoning. Each message they send waits for you.":
    "访客与你看到相同的会话内容，包括命令输出和 Agent 推理。访客发送的每条消息都需你批准。",
  "The host account changed.": "执行电脑的账号已改变。",
